import { DomGenerator } from '../index';
import deindent from '../../../utils/deindent';
import visit from '../visit';
import Block from '../Block';
import getStaticAttributeValue from '../../../utils/getStaticAttributeValue';
import { Node } from '../../../interfaces';
import { State } from '../interfaces';

export default function visitSlot(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	elementStack: Node[],
	componentStack: Node[]
) {
	const slotName = getStaticAttributeValue(node, 'name') || 'default';
	generator.slots.add(slotName);

	const content_name = block.getUniqueName(`slot_content_${slotName}`);
	block.addVariable(content_name, `#component._slotted.${slotName}`);

	const needsAnchorBefore = node.prev ? node.prev.type !== 'Element' : !state.parentNode;
	const needsAnchorAfter = node.next ? node.next.type !== 'Element' : !state.parentNode;

	const anchorBefore = needsAnchorBefore
		? block.getUniqueName(`${content_name}_before`)
		: (node.prev && node.prev.var) || 'null';

	const anchorAfter = needsAnchorAfter
		? block.getUniqueName(`${content_name}_after`)
		: (node.next && node.next.var) || 'null';

	if (needsAnchorBefore) block.addVariable(anchorBefore);
	if (needsAnchorAfter) block.addVariable(anchorAfter);

	block.builders.create.pushCondition(`!${content_name}`);
	block.builders.hydrate.pushCondition(`!${content_name}`);
	block.builders.mount.pushCondition(`!${content_name}`);
	block.builders.unmount.pushCondition(`!${content_name}`);
	block.builders.destroy.pushCondition(`!${content_name}`);

	node.children.forEach((child: Node) => {
		visit(generator, block, state, child, elementStack, componentStack);
	});

	block.builders.create.popCondition();
	block.builders.hydrate.popCondition();
	block.builders.mount.popCondition();
	block.builders.unmount.popCondition();
	block.builders.destroy.popCondition();

	// TODO can we use an else here?
	if (state.parentNode) {
		block.builders.mount.addBlock(deindent`
			if (${content_name}) {
				${needsAnchorBefore && `@appendNode(${anchorBefore} || (${anchorBefore} = @createComment()), @getSlotTarget(${state.parentNode}));`}
				@appendNode(${content_name}, @getSlotTarget(${state.parentNode}));
				${content_name}._svelte_parent = @getSlotTarget(${state.parentNode});
				${needsAnchorAfter && `@appendNode(${anchorAfter} || (${anchorAfter} = @createComment()), @getSlotTarget(${state.parentNode}));`}
			}
		`);
	} else {
		block.builders.mount.addBlock(deindent`
			if (${content_name}) {
				${needsAnchorBefore && `@insertNode(${anchorBefore} || (${anchorBefore} = @createComment()), #target, anchor);`}
				@insertNode(${content_name}, #target, anchor);
				${content_name}._svelte_parent = #target;
				${needsAnchorAfter && `@insertNode(${anchorAfter} || (${anchorAfter} = @createComment()), #target, anchor);`}
			}
		`);
	}

	// if the slot is unmounted, move nodes back into the document fragment,
	// so that it can be reinserted later
	// TODO so that this can work with public API, component._slotted should
	// be all fragments, derived from options.slots. Not === options.slots
	// TODO can we use an else here?
	if (anchorBefore === 'null' && anchorAfter === 'null') {
		block.builders.unmount.addBlock(deindent`
			if (${content_name}) {
				@reinsertChildren(${state.parentNode}, ${content_name});
			}
		`);
	} else if (anchorBefore === 'null') {
		block.builders.unmount.addBlock(deindent`
			if (${content_name}) {
				@reinsertBefore(${anchorAfter}, ${content_name});
			}
		`);
	} else if (anchorAfter === 'null') {
		block.builders.unmount.addBlock(deindent`
			if (${content_name}) {
				@reinsertAfter(${anchorBefore}, ${content_name});
			}
		`);
	} else {
		block.builders.unmount.addBlock(deindent`
			if (${content_name}) {
				@reinsertBetween(${anchorBefore}, ${anchorAfter}, ${content_name});
				@detachNode(${anchorBefore});
				@detachNode(${anchorAfter});
			}
		`);
	}
}

import CodeBuilder from '../../utils/CodeBuilder';
import deindent from '../../utils/deindent';
import { DomGenerator } from './index';
import { Node } from '../../interfaces';
import shared from './shared';

export interface BlockOptions {
	name: string;
	generator?: DomGenerator;
	expression?: Node;
	context?: string;
	key?: string;
	contexts?: Map<string, string>;
	indexes?: Map<string, string>;
	changeableIndexes?: Map<string, boolean>;
	contextDependencies?: Map<string, string[]>;
	params?: string[];
	indexNames?: Map<string, string>;
	listNames?: Map<string, string>;
	indexName?: string;
	listName?: string;
	dependencies?: Set<string>;
}

export default class Block {
	generator: DomGenerator;
	name: string;
	expression: Node;
	context: string;

	key: string;
	first: string;

	contexts: Map<string, string>;
	indexes: Map<string, string>;
	changeableIndexes: Map<string, boolean>;
	contextDependencies: Map<string, string[]>;
	dependencies: Set<string>;
	params: string[];
	indexNames: Map<string, string>;
	listNames: Map<string, string>;
	indexName: string;
	listName: string;

	builders: {
		init: CodeBuilder;
		create: CodeBuilder;
		claim: CodeBuilder;
		hydrate: CodeBuilder;
		mount: CodeBuilder;
		intro: CodeBuilder;
		update: CodeBuilder;
		outro: CodeBuilder;
		unmount: CodeBuilder;
		detachRaw: CodeBuilder;
		destroy: CodeBuilder;
	};

	hasIntroMethod: boolean;
	hasOutroMethod: boolean;
	outros: number;

	aliases: Map<string, string>;
	variables: Map<string, string>;
	getUniqueName: (name: string) => string;

	hasUpdateMethod: boolean;
	autofocus: string;

	constructor(options: BlockOptions) {
		this.generator = options.generator;
		this.name = options.name;
		this.expression = options.expression;
		this.context = options.context;

		// for keyed each blocks
		this.key = options.key;
		this.first = null;

		this.contexts = options.contexts;
		this.indexes = options.indexes;
		this.changeableIndexes = options.changeableIndexes;
		this.contextDependencies = options.contextDependencies;
		this.dependencies = new Set();

		this.params = options.params;
		this.indexNames = options.indexNames;
		this.listNames = options.listNames;

		this.listName = options.listName;

		this.builders = {
			init: new CodeBuilder(),
			create: new CodeBuilder(),
			claim: new CodeBuilder(),
			hydrate: new CodeBuilder(),
			mount: new CodeBuilder(),
			intro: new CodeBuilder(),
			update: new CodeBuilder(),
			outro: new CodeBuilder(),
			unmount: new CodeBuilder(),
			detachRaw: new CodeBuilder(),
			destroy: new CodeBuilder(),
		};

		this.hasIntroMethod = false; // a block could have an intro method but not intro transitions, e.g. if a sibling block has intros
		this.hasOutroMethod = false;
		this.outros = 0;

		this.aliases = new Map();
		this.variables = new Map();
		this.getUniqueName = this.generator.getUniqueNameMaker(options.params);

		this.hasUpdateMethod = false; // determined later
	}

	addDependencies(dependencies: string[]) {
		dependencies.forEach(dependency => {
			this.dependencies.add(dependency);
		});
	}

	addElement(
		name: string,
		renderStatement: string,
		claimStatement: string,
		parentNode: string
	) {
		const isToplevel = !parentNode;

		this.addVariable(name);
		this.builders.create.addLine(`${name} = ${renderStatement};`);
		this.builders.claim.addLine(`${name} = ${claimStatement};`);

		this.mount(name, parentNode);

		if (isToplevel) {
			this.builders.unmount.addLine(`@detachNode(${name});`);
		}
	}

	addVariable(name: string, init?: string) {
		if (this.variables.has(name) && this.variables.get(name) !== init) {
			throw new Error(
				`Variable '${name}' already initialised with a different value`
			);
		}

		this.variables.set(name, init);
	}

	alias(name: string) {
		if (!this.aliases.has(name)) {
			this.aliases.set(name, this.getUniqueName(name));
		}

		return this.aliases.get(name);
	}

	child(options: BlockOptions) {
		return new Block(Object.assign({}, this, options, { parent: this }));
	}

	contextualise(expression: Node, context?: string, isEventHandler?: boolean) {
		return this.generator.contextualise(
			this,
			expression,
			context,
			isEventHandler
		);
	}

	findDependencies(expression: Node) {
		return this.generator.findDependencies(
			this.contextDependencies,
			this.indexes,
			expression
		);
	}

	mount(name: string, parentNode: string) {
		if (parentNode) {
			this.builders.mount.addLine(`@appendNode(${name}, @getSlotTarget(${parentNode}));`);
		} else {
			this.builders.mount.addLine(`@insertNode(${name}, #target, anchor);`);
		}
	}

	toString() {
		let introing;
		const hasIntros = !this.builders.intro.isEmpty();
		if (hasIntros) {
			introing = this.getUniqueName('introing');
			this.addVariable(introing);
		}

		let outroing;
		const hasOutros = !this.builders.outro.isEmpty();
		if (hasOutros) {
			outroing = this.alias('outroing');
			this.addVariable(outroing);
		}

		if (this.autofocus) {
			this.builders.mount.addLine(`${this.autofocus}.focus();`);
		}

		// minor hack – we need to ensure that any {{{triples}}} are detached first
		this.builders.unmount.addBlockAtStart(this.builders.detachRaw);

		const properties = new CodeBuilder();

		let localKey;
		if (this.key) {
			localKey = this.getUniqueName('key');
			properties.addBlock(`key: ${localKey},`);
		}

		if (this.first) {
			properties.addBlock(`first: null,`);
			this.builders.hydrate.addLine(`this.first = ${this.first};`);
		}

		if (this.builders.create.isEmpty()) {
			properties.addBlock(`create: @noop,`);
		} else {
			properties.addBlock(deindent`
				create: function() {
					${this.builders.create}
					${!this.builders.hydrate.isEmpty() && `this.hydrate();`}
				},
			`);
		}

		if (this.generator.hydratable) {
			if (this.builders.claim.isEmpty()) {
				properties.addBlock(`claim: @noop,`);
			} else {
				properties.addBlock(deindent`
					claim: function(nodes) {
						${this.builders.claim}
						${!this.builders.hydrate.isEmpty() && `this.hydrate();`}
					},
				`);
			}
		}

		if (!this.builders.hydrate.isEmpty()) {
			properties.addBlock(deindent`
				hydrate: function(nodes) {
					${this.builders.hydrate}
				},
			`);
		}

